use vstd::prelude::*;

verus! {
    /// Returns true iff all elements of `arr` are equal to `arr[0]`.
    ///
    /// An empty array or a singleton array vacuously satisfies the property.
    ///
    /// Specification:
    ///   result == (forall j: nat. 1 <= j < arr@.len() ==> arr@.index(j) == arr@.index(0))
    fn has_only_one_distinct_element(arr: &Vec<i32>) -> bool
        ensures
            result == (forall |j: nat| 1 <= j && j < arr@.len() ==> arr@.index(j) == arr@.index(0)),
    {
        let n: usize = arr.len();
        let mut i: usize = 1;
        // We maintain:
        //   1) i ≤ n
        //   2) n as nat == arr@.len()
        //   3) for all j with 1 ≤ j < i, arr@.index(j) == arr@.index(0)
        // We decrease on (n - i).
        while i < n
            invariant
                i <= n,
                (n as nat) == arr@.len(),
                forall |j: nat| 1 <= j && j < (i as nat) ==> arr@.index(j) == arr@.index(0),
            decreases n - i,
        {
            if arr[i] != arr[0] {
                //
                // We are about to return false, so we must show
                //   false == (forall j. 1 ≤ j < arr@.len() ==> arr@.index(j) == arr@.index(0))
                // i.e. show the right‐hand side is false by providing a counterexample j = i.
                //
                // First connect the runtime inequality to the spec‐level vector:
                assert(arr@.index(i as nat) != arr@.index(0));
                // Now exhibit that the universal quantification fails:
                assert(!(forall |j: nat| 1 <= j && j < arr@.len() ==> arr@.index(j) == arr@.index(0))) by {
                    // j = i is a witness
                    assert(1 <= i as nat);
                    assert(i as nat < arr@.len());
                    assert(arr@.index(i as nat) != arr@.index(0));
                };
                return false;
            }
            i = i + 1;
        }
        // Upon loop exit we have i == n and the invariant
        //   forall j. 1 ≤ j < i ⇒ arr@.index(j) == arr@.index(0)
        // together with i == n gives exactly the postcondition.
        true
    }
}

fn main() {
    // Example usages
    let v0: Vec<i32> = Vec::new();
    assert!(has_only_one_distinct_element(&v0));

    let v1 = vec![7];
    assert!(has_only_one_distinct_element(&v1));

    let v2 = vec![3,3,3,3];
    assert!(has_only_one_distinct_element(&v2));

    let v3 = vec![1,2,1];
    assert!(!has_only_one_distinct_element(&v3));
}